Here is the commit message:
soc: microchip: mpfs: Fix memory leak in
 mpfs_sys_controller_probe()

In mpfs_sys_controller_probe(), if of_get_mtd_device_by_node() fails,
the function returns immediately without freeing the allocated memory
for sys_controller, leading to a memory leak.

Fix this by jumping to the out_free label to ensure the memory is
properly freed.

Also, consolidate the error handling for the mbox_request_channel()
failure case to use the same label.

Fixes: 742aa6c563d2 ("soc: microchip: mpfs: enable access to the system controller's flash")
Co-developed-by: Jianhao Xu <jianhao.xu@seu.edu.cn>
Signed-off-by: Jianhao Xu <jianhao.xu@seu.edu.cn>
Signed-off-by: Zilin Guan <zilin@seu.edu.cn>
Signed-off-by: Conor Dooley <conor.dooley@microchip.com>

Here is the root cause:
In `mpfs_sys_controller_probe()`, when `of_get_mtd_device_by_node()` fails, the function returns immediately via `dev_err_probe()` without freeing the `sys_controller` memory previously allocated by `kzalloc()`, causing a memory leak.

Here is the patch:

 static int mpfs_sys_controller_probe(struct platform_device *pdev)
 {
 	struct device *dev = &pdev->dev;
 	struct mpfs_sys_controller *sys_controller;
 	struct device_node *np;
 	int i, ret;

 	sys_controller = kzalloc(sizeof(*sys_controller), GFP_KERNEL);
 	if (!sys_controller)
 		return -ENOMEM;

 	np = of_parse_phandle(dev->of_node, "microchip,bitstream-flash", 0);
 	if (!np)
 		goto no_flash;

 	sys_controller->flash = of_get_mtd_device_by_node(np);
 	of_node_put(np);
-	if (IS_ERR(sys_controller->flash))
-		return dev_err_probe(dev, PTR_ERR(sys_controller->flash), "Failed to get flash\n");
+	if (IS_ERR(sys_controller->flash)) {
+		ret = dev_err_probe(dev, PTR_ERR(sys_controller->flash), "Failed to get flash\n");
+		goto out_free;
+	}

 no_flash:
 	sys_controller->client.dev = dev;
 	sys_controller->client.rx_callback = mpfs_sys_controller_rx_callback;
 	sys_controller->client.tx_block = 1U;
 	sys_controller->client.tx_tout = msecs_to_jiffies(MPFS_SYS_CTRL_TIMEOUT_MS);

 	sys_controller->chan = mbox_request_channel(&sys_controller->client, 0);
 	if (IS_ERR(sys_controller->chan)) {
 		ret = dev_err_probe(dev, PTR_ERR(sys_controller->chan),
 				    "Failed to get mbox channel\n");
-		kfree(sys_controller);
-		return ret;
+		goto out_free;
 	}

 	init_completion(&sys_controller->c);
 	kref_init(&sys_controller->consumers);

 	platform_set_drvdata(pdev, sys_controller);


 	for (i = 0; i < ARRAY_SIZE(subdevs); i++) {
 		subdevs[i].dev.parent = dev;
 		if (platform_device_register(&subdevs[i]))
 			dev_warn(dev, "Error registering sub device %s\n", subdevs[i].name);
 	}

 	dev_info(&pdev->dev, "Registered MPFS system controller\n");

 	return 0;
+
+out_free:
+	kfree(sys_controller);
+	return ret;
 }



